prog='''def transform(grid):
    """Complete drawn rectangle figures: fill background gaps with 2 along the
    perimeter of the structure's bounding box, and complete internal straight
    line segments (contiguous runs) so they reach opposite edges."""
    h, w = len(grid), len(grid[0])
    g = [r[:] for r in grid]
    from collections import Counter
    cnt = Counter(v for r in g for v in r)
    bg = cnt.most_common(1)[0][0]
    fill = 2
    pts = [(r, c) for r in range(h) for c in range(w) if g[r][c] != bg]
    r0 = min(p[0] for p in pts); r1 = max(p[0] for p in pts)
    c0 = min(p[1] for p in pts); c1 = max(p[1] for p in pts)

    def fill_row_gaps(r, ca, cb):
        cells = [c for c in range(ca, cb + 1) if g[r][c] != bg]
        for a, b in zip(cells, cells[1:]):
            for c in range(a + 1, b):
                if g[r][c] == bg:
                    g[r][c] = fill

    def fill_col_gaps(c, ra, rb):
        cells = [r for r in range(ra, rb + 1) if g[r][c] != bg]
        for a, b in zip(cells, cells[1:]):
            for r in range(a + 1, b):
                if g[r][c] == bg:
                    g[r][c] = fill

    # perimeter of bounding box
    fill_row_gaps(r0, c0, c1); fill_row_gaps(r1, c0, c1)
    fill_col_gaps(c0, r0, r1); fill_col_gaps(c1, r0, r1)
    # internal contiguous segments: extend to opposite edges
    for r in range(r0 + 1, r1):
        c = c0 + 1
        while c < c1:
            if g[r][c] != bg and g[r][c] != fill:
                s = c
                while c + 1 < c1 and g[r][c + 1] != bg and c + 1 <= c1:
                    c += 1
                    if g[r][c] == bg: break
                # segment s..c (contiguous non-bg) strictly inside
                if c > s and s > c0:
                    for cc in range(s - 1, c0, -1):
                        if g[r][cc] == bg: g[r][cc] = fill
                        else: break
                if c > s:
                    for cc in range(c + 1, c1):
                        if g[r][cc] == bg: g[r][cc] = fill
                        else: break
            c += 1
    for c in range(c0 + 1, c1):
        r = r0 + 1
        while r < r1:
            if g[r][c] != bg and g[r][c] != fill:
                s = r
                while r + 1 < r1 and g[r + 1][c] != bg:
                    r += 1
                    if g[r][c] == bg: break
                if r > s and s > r0:
                    for rr in range(s - 1, r0, -1):
                        if g[rr][c] == bg: g[rr][c] = fill
                        else: break
                if r > s:
                    for rr in range(r + 1, r1):
                        if g[rr][c] == bg: g[rr][c] = fill
                        else: break
            r += 1
    return g
'''
